// Builds STATUS.md: every card and how many scenarios test it. Run with
// --check in CI to fail when the committed report is out of date.
import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const sets = readdirSync(join(root, "cards"))
  .filter((f) => f.endsWith(".json"))
  .map((f) => f.replace(".json", ""))
  .sort();

const lines = [
  "# Card status",
  "",
  "Generated by `pnpm status`. A card is **tested** when at least one scenario in",
  "`scenarios/<SET>/` starts with its card number and passes in CI.",
  "",
];
for (const set of sets) {
  const cards = JSON.parse(readFileSync(join(root, "cards", `${set}.json`), "utf8"));
  const dir = join(root, "scenarios", set);
  const scenarios = existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith(".json")) : [];
  const count = (id) => scenarios.filter((f) => f.startsWith(`${id}-`)).length;
  const tested = cards.filter((c) => count(c.id) > 0).length;
  lines.push(`## ${set}: ${tested} of ${cards.length} tested`, "");
  lines.push("| Card | Name | Scenarios | Status |", "| --- | --- | --- | --- |");
  for (const c of cards) {
    lines.push(
      `| ${c.id} | ${c.name} | ${count(c.id)} | ${count(c.id) > 0 ? "tested" : "not tested"} |`,
    );
  }
  lines.push("");
}
const report = await format(lines.join("\n"), { parser: "markdown", printWidth: 100 });
const file = join(root, "STATUS.md");

if (process.argv.includes("--check")) {
  if (!existsSync(file) || readFileSync(file, "utf8") !== report) {
    console.error("STATUS.md is out of date. Run `pnpm status` and commit the result.");
    process.exit(1);
  }
  console.log("STATUS.md is up to date.");
} else {
  writeFileSync(file, report);
  console.log("Wrote STATUS.md.");
}
